// SigSeal artifacts - signature round-trip demo
var crypto = require("crypto");
var msg = "artifact:SigSeal";
var h = crypto.createHash("sha256").update(msg).digest("hex");
console.log("Scheme: SigSeal");
console.log("Artifact digest: " + h.slice(0, 32) + "...");
var sig = crypto.createHmac("sha256", "demo-key").update(msg).digest("hex");
console.log("Signature: " + sig.slice(0, 32) + "...");
console.log("Verify recompute matches -> " + (crypto.createHmac("sha256", "demo-key").update(msg).digest("hex") === sig ? "PASS" : "FAIL"));

